var t=`1167-mole-poblano`;var n=`world-1167`;var a=`MX`;var o=`central-america-caribbean`;var s=8;var r=104;var l={en:`Mole Poblano`,ua:`Моле поблано`};var c={en:`Mole Poblano is a dish from Mexico prepared with dried ancho chilies, dried chipotle chilies, dried pasilla chilies, white sesame seeds. This is a home-scale version with measured ingredients in the individual steps where they are used. Mulato chile is not in the catalog; chipotle, ancho and pasilla give a different mole from a canonical poblano.`,ua:`Моле поблано, страва кухні країни Мексика, яку готують із таких продуктів: сушений перець анчо, сушений перець чипотле, сушений перець пасілья, білий кунжут. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Чилі мулато немає в каталозі; чипотле, анчо й пасілья дають інший смак, ніж канонічний моле поблано.`};var d=[{en:`Toast these ingredients over medium heat for about 10 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 10 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:10,i:[[`dried-ancho-chilies`,4,`pcs`],[`dried-chipotle-chilies`,2,`pcs`],[`dried-pasilla-chilies`,3,`pcs`],[`white-sesame-seeds`,80,`g`],[`peanut`,75,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,160,`g`],[`garlic`,5,`clove`],[`tomato`,240,`g`],[`canola-oil`,40,`ml`]]},{en:`Puree the toasted, softened chilies with tomato, nuts, spices and a little stock into a smooth dark mole; add chocolate gradually and taste before braising chicken.`,ua:`Подрібніть підсмажені розм’якшені чилі з томатом, горіхами, спеціями й бульйоном на гладкий темний моле; поступово додайте шоколад та спробуйте перед тушкуванням курки.`,t:[`mixing`],m:12,i:[[`dark-chocolate`,100,`g`],[`ground-cinnamon`,4,`g`],[`ground-cloves`,2,`g`],[`raisin`,65,`g`],[`white-bread`,110,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`chicken-thigh`,880,`g`],[`chicken-stock`,1150,`ml`]]},{en:`Continue simmering the sauce from the previous step uncovered until concentrated and thick enough to coat the ingredients.`,ua:`Продовжуйте виварювати соус із попереднього етапу без кришки, доки він загусне та вкриватиме складники.`,t:[`reducing-sauce`],m:20,i:[]}];var h={slug:t,id:n,country:`MX`,region:o,servings:8,minutes:104,title:l,text:c,steps:d};export{a as country,h as default,n as id,r as minutes,o as region,s as servings,t as slug,d as steps,c as text,l as title};